        fatherName: (fatherIdx !== -1 && row[fatherIdx]) ? row[fatherIdx].toString() : "",
        phone: phone.toString().replace(/^'+/, ""),
        email: (emailIdx !== -1 && row[emailIdx]) ? row[emailIdx].toString() : "",
        state: (stateIdx !== -1 && row[stateIdx]) ? row[stateIdx].toString() : "",
